powerpagecomponent.searchcontent:
Home{% include 'OP365 Supplier Style' %} {% assign supplier = false %}{% if user %}{% for r in user.roles %}{% if r == 'Supplier' %}{% assign supplier = true %}{% endif %}{% endfor %}{% endif %} {% if supplier %}
<script>
  location.replace('/dashboard/');
</script>
{% endif %}
<div class="op-shell" style="justify-content:center;align-items:center">
  <div style="max-width:560px;text-align:center;padding:48px 16px">
    <h1 style="font-weight:700">Supplier portal</h1>
    <p>Answer requests for quotation, confirm purchase orders, follow invoices and keep your company documents up to date.</p>
    {% if user %}
    <p>Your account is not yet linked to a supplier. Ask your customer to enable it.</p>
    {% else %}
    <p><a class="btn btn-primary" href="/SignIn?returnUrl=%2Fdashboard%2F">Sign in</a> <a class="btn btn-outline-primary ms-2" href="/Account/Login/Register?returnUrl=%2Fdashboard%2F">Register</a></p>
    {% endif %}
  </div>
</div>
<div class="row sectionBlockLayout text-start" style="display: flex; flex-wrap: wrap; margin: 0px; min-height: auto; padding: 8px;">
  <div class="container" style="padding: 0px; display: flex; flex-wrap: wrap;"><div class="col-lg-12 columnBlockLayout" style="flex-grow: 1; display: flex; flex-direction: column; min-width: 250px;"></div></div>
</div>
Home
